'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const ui=fs.readFileSync('sanabil-plan-calendar.js','utf8');
const live=fs.readFileSync('sanabil-live-v12.js','utf8');
const index=fs.readFileSync('index.html','utf8');
const migration=fs.readFileSync('supabase/migrations/20261025012200_complex_calendar_batched_guarded.sql','utf8');
new vm.Script(ui);
assert(index.includes('20261029-v13.8.74'),'release is updated');
assert(index.includes('/sanabil-plan-calendar.js?v=20261025-bulk-default1'),'cache-busted calendar');
assert(index.includes('/sanabil-live-v12.js?v=20261029-v13.8.74'),'cache-busted host app');
assert(live.includes('SanabilPlanCalendar.open({selectedCircle:selectedPlanCircle})'),'calendar loads server-managed scope');
assert(ui.includes("client.rpc('get_calendar_management_scope_guarded')"),'manager scope comes from checked database');
assert(ui.includes('authorized.flatMap(g=>g.circles'),'authorized groups are flattened exclusively');
assert(ui.includes("for(const complex of authorized)"),'UI renders each authorized complex');
assert(ui.includes("const ids=complex.circles.map(c=>c.id)"),'complex-level select only chooses children');
assert(ui.includes("master.indeterminate="),'partial selections are represented');
assert(ui.includes("checkbox.onchange="),'individual rings can be toggled independently');
assert(ui.includes('selectedCircle&&circles.some'),'only real authorized selected circles default on');
assert(ui.includes("client.rpc('apply_calendar_days_bulk_guarded'"),'bounded range classification is used');
assert(!ui.includes('p_batch_size:1'),'browser never waits on serial student transactions');
assert(ui.includes('lastBreakdown=all.filter'),'progress details survive calendar refreshing');
assert(ui.includes("console.warn('Calendar bulk classification',e)"),'retain technical server error in logs');
assert(ui.includes("explainError(e)"),'provide translated error reason to user');
assert(ui.includes('get_calendar_reflow_status_guarded'),'progress is independently queryable and job is persistent');
assert(!ui.includes("client.rpc('set_day_type_guarded'"),'old all-at-once circle operation removed');
assert(!ui.includes('نجح تحديث '+""+'0 حلقة.'),'no misleading partial status');
assert(migration.includes('private.can_access(c.org_id,c.complex_id,c.id'),'scope filters unauthorized manager circles');
assert(migration.includes("array['admin','manager','supervisor']"),'teacher cannot classify entire circle with helper');
assert(migration.includes('pg_advisory_xact_lock'),'concurrent admins are serialized');
assert(migration.includes('p_batch_size integer DEFAULT 1'),'backend safe batch default');
assert(migration.includes('NOT EXISTS(SELECT 1 FROM public.student_day_types'),'repeat step skips already-processed students');
assert(migration.includes("IF v_remaining=0 THEN"),'circle-wide classification is finalized only when complete');
assert(migration.includes("DELETE FROM public.student_day_types"),'completed checkpoints consolidated into circle default');
assert(migration.includes("REVOKE ALL ON FUNCTION public.apply_calendar_day_step_guarded"),'no public anonymous helper rights');
assert(migration.includes("REVOKE ALL ON FUNCTION public.get_calendar_management_scope_guarded"),'no anonymous scope');
const ctx={window:{},document:{},console};vm.runInNewContext(ui,ctx,{timeout:2000});
const calendar=ctx.window.SanabilPlanCalendar;
assert.equal(calendar.officialFor('2026-10-25'),'إجازة إضافية للمدينة المنورة');
assert.equal(calendar.officialFor('2028-11-24'),'','future years not silently approved');
assert.equal(calendar.referenceFor('2028-11-24'),'إجازة الخريف للمدينة المنورة');
console.log('PASS: scoped complex/circle calendar; bounded resumable server operations; cancellation, status, later-year nonactivation, deployment release');
